% --- Archon declaration ledger (added iter-008, coverage-debt repair) ---
% Entries for the full Coulomb-scattering formalization layer of the covered
% file, restated first-hand from the Lean source; \\uses{} mirrors the Lean
% dependencies.  The two official hints on the problem page (Hint 1: the
% eccentricity formula; Hint 2: the polar conic equation) are encoded as
% \\emph{derivable bridge lemmas}, not assumed laws; every numeric answer
% value (-16.60, the rounding bands, the 67/4 consequences) is conclusion-side.

\\section*{Declaration ledger (autoformalization contracts)}

\\subsection*{Ambient plane and constants}

\\begin{definition}[Scattering plane, dot product, and perpendicular bracket]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:Plane}
\\lean{IPhO2026.Problem1.B2.Plane}
\\lean{IPhO2026.Problem1.B2.dot}
\\lean{IPhO2026.Problem1.B2.perp}
The ambient centre-of-mass plane "'$'"\\mathrm{Plane} = \\mathbb{R}"'^2$ (the
Euclidean space on $'"\\mathrm{Fin}\\ 2"'$) on which the relative motion lives,
with the standard scalar product $'"\\langle v, w\\rangle = v_x w_x + v_y w_y"'$
and the oriented planar bracket $'"\\mathrm{perp}\\ v\\ w = v_x w_y - v_y w_x"'$ --
the signed $z$-component of the 2D cross product, positive exactly when $w$
is reached from $v$ by a counterclockwise rotation of less than
$180''^{'"\\circ}"'$.  The bracket carries the rotation sense of the deflection
(branch/orientation bookkeeping) and the planar angular momentum.
'"\\end{definition}

\\begin{definition}[Universal constants of the scenario]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
\\lean{IPhO2026.Problem1.B2.particleMass}
\\lean{IPhO2026.Problem1.B2.hbar}
\\lean{IPhO2026.Problem1.B2.coulombK}
\\lean{IPhO2026.Problem1.B2.elementaryCharge}
\\lean{IPhO2026.Problem1.B2.bohrRadius}
The fixed physical constants, kept abstract (opaque) so that nothing about
the target can be obtained by unfolding: the inertial mass "'$m$ of each
particle (electron and positron, kg), the reduced Planck constant $'"\\hbar"'$
(J'"\\,s), the Coulomb constant "'$k = 1/(4'"\\pi\\varepsilon_0)"'$
(N'"\\,m"'$''^2$'"\\,C"'$''^{-2}$), the elementary charge
magnitude $e$ (the electron carries $-e$, the positron $+e$; C), and the
Bohr radius $a_0 = 4'"\\pi\\varepsilon_0\\hbar"'^2/(m e''^2) = '"\\hbar"'^2/(k m e''^2)$
(m).
'"\\end{definition}

\\begin{definition}[Scaling regime certificates]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime}
\\lean{IPhO2026.Problem1.B2.ScalingRegime}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
The positivity certificates for all constants, "'$m, '"\\hbar, k, e, a_0 > 0"'$,
together with the defining Bohr-radius identity
$a_0 = '"\\hbar"'^2/(k'"\\,m\\,e"'^2)$ (the page'"'s
"'$a_0 = 4'"\\pi\\varepsilon_0\\hbar"'^2/(m e''^2)$ with $k = 1/(4'"\\pi\\varepsilon_0)"'$),
packaged as a single hypothesis structure carried by everything downstream.
'"\\end{definition}

\\subsection*{Angular-momentum factor}

\\begin{definition}[Angular-momentum factor predicate]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor}
\\lean{IPhO2026.Problem1.B2.IsAngularMomentumFactor}
The predicate on a real "'$'"\\mu"'$ asserting $'"\\mu > 0"'$, i.e.'"\\ that "'$'"\\mu"'$ is a
legitimate dimensionless factor making the per-particle angular momentum
$'"\\mu\\hbar"'$ about the centre of mass positive.
'"\\end{definition}

\\begin{definition}[The unbound-case value "'$'"\\mu = 15/2"'$]
'"\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
\\lean{IPhO2026.Problem1.B2.unboundMu}
The value "'$'"\\mu = 15/2"'$ of subquestion B.2 (the unbound, hyperbolic case).
'"\\end{definition}

\\begin{lemma}["'$15/2$ is an angular-momentum factor]
'"\\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu_isAngularMomentumFactor}
\\lean{IPhO2026.Problem1.B2.unboundMu_isAngularMomentumFactor}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
"'$'"\\mathrm{IsAngularMomentumFactor}(15/2)"'$ holds.
'"\\end{lemma}
\\begin{proof}
Unfold both definitions; "'$15/2 > 0$ by arithmetic.
'"\\end{proof}

\\subsection*{Scattering data and governing laws}

\\begin{definition}[Two-body Coulomb scattering data]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:Plane, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
The B.1-style two-body record of the isolated, classical, non-relativistic
electron--positron pair with purely electrostatic interaction, with the
two-body-to-one-body reduction encoded.  Data: the CM-frame relative
curve "'$'"\\mathrm{sep} : \\mathbb{R} \\to \\mathrm{Plane}"'$
($r_{e+}(t) - r_{e-}(t)$, m), initial data ($r_0 = 100'"\\,a_0"'$, antiparallel
CM velocities $'"\\pm v_0"'$ perpendicular to the separation with the Fig.-1b
orientation $'"\\mathrm{perp}\\ \\mathrm{sep0}\\ v_0 = r_0 v_0"'$, relative speed
$2v_0$, per-particle angular momentum $'"\\mu\\hbar"'$ certified by
$m v_0 (r_0/2) = '"\\mu \\hbar"'$), the reduced mass $m_{'"\\mathrm{red}} = m/2"'$,
the total angular momentum $L = 2'"\\mu\\hbar"'$ and total energy $E$, and a
continuous polar angle.  Governing-law fields: Coulomb'"'s law for the
conserved energy, Newton's equation for the reduced particle under the
attractive Coulomb force, angular-momentum conservation
"'$'"\\mathrm{perp}(\\mathrm{sep}, \\dot{\\mathrm{sep}}) = L/m_{\\mathrm{red}}"'$, the
radial-energy identity multiplied out by $r''^2 > 0$, the turning point at
$t = 0$ (radial speed zero), twice-continuous-differentiable regularity,
and $'"\\mathrm{sep}\\,t \\neq 0"'$ for all $t$.  No orbit shape, asymptotic
velocity, or deflection angle appears among the fields; those are
conclusion-side.
'"\\end{definition}

\\begin{lemma}[Initial separation is positive]
\\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:initial_separation_pos}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.initial_separation_pos}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime}
The Fig.-1b readout satisfies "'$0 < r_0$.
'"\\end{lemma}
\\begin{proof}
Rewrite "'$r_0 = 100'"\\,a_0"'$; the product $100 '"\\cdot a_0"'$ is positive since
$a_0 > 0$.
'"\\end{proof}

\\begin{lemma}[Total angular momentum value]
\\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_angular_momentum_value}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.total_angular_momentum_value}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu}
The total angular momentum has the value "'$L = 2'"\\,(\\mu\\hbar) = 15\\hbar"'$ for
$'"\\mu = 15/2"'$.
'"\\end{lemma}
\\begin{proof}
Rewrite "'$L$ by its defining field as twice the per-particle contribution,
then substitute the given identity $m v_0 (r_0/2) = '"\\mu\\hbar"'$.
'"\\end{proof}

\\begin{definition}[Turning-point quadratic]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.turningQuadratic}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
The effective radial quadratic
"'$Q(r) = E r''^2 + k e''^2 r - L''^2/(2 m_{'"\\mathrm{red}})"'$: along the trajectory
the radial-energy identity gives
$Q(r) = '"\\tfrac{1}{2} m_{\\mathrm{red}}\\, \\dot r"'^{'"\\,2} r"'^2$, so $Q(r) = 0$
exactly at turning points.
'"\\end{definition}

\\begin{lemma}[Periapsis at the initial separation]
\\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.turningQuadratic_periapsis}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
The initial separation is a turning point (the periapsis of the unbound
orbit): "'$Q(r_0) = 0$.
'"\\end{lemma}
\\begin{proof}
Evaluate the radial-energy law at "'$t = 0$: $'"\\mathrm{sep}\\,0 = \\mathrm{sep0}"'$
has norm $r_0$ and the radial speed vanishes there, so the right-hand side
is zero; unfold $Q$ and read off the equality.
'"\\end{proof}

\\begin{definition}[Semilatus rectum]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:semilatusRectum}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.semilatusRectum}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
The semilatus rectum "'$p = L''^2/(m_{'"\\mathrm{red}}\\,k\\,e"'^2)$ of the reduced
one-body problem (m): the geometric scale of the conic in Hint 2.
'"\\end{definition}

\\begin{definition}[Squared eccentricity]
\\label{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq}
\\lean{IPhO2026.Problem1.B2.CoulombScatteringData.eccentricitySq}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:constants}
The dimensionless squared eccentricity
"'$'"\\varepsilon"'^2 = 1 + 2 E L''^2/(m_{'"\\mathrm{red}} (k e"'^2)''^2)$; for equal
masses $m_{'"\\mathrm{red}} = m/2"'$ reconciles the denominator with the page'"'s
Hint-1 form "'$'"\\varepsilon"'^2 = 1 + 4 E L''^2/(k''^2 e''^4 m)$.
'"\\end{definition}

\\subsection*{Unboundness and conic bridges}

\\begin{theorem}[Positivity of the total energy (unboundness)]
\\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}
\\lean{IPhO2026.Problem1.B2.total_energy_pos}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor}
For "'$'"\\mu = 15/2"'$ the total energy is the Fig.-1b value
$E = '"\\mu"'^2/2500 - 1/200$ in units of $'"\\hbar"'^2/(m a_0''^2)$, i.e.'"\\
"'$E = 7/400 > 0$: the pair is unbound (hyperbolic scattering).
'"\\end{theorem}
\\begin{proof}
Evaluate the energy law at "'$t = 0$: by the transverse configuration the
energy is kinetic plus Coulomb,
$E = 2'"\\cdot\\tfrac12 m v_0"'^2 - k e''^2/r_0$; eliminate $v_0$ via
$m v_0 (r_0/2) = '"\\mu\\hbar"'$ with $r_0 = 100'"\\,a_0"'$ and the Bohr-radius identity
$a_0 = '"\\hbar"'^2/(k m e''^2)$, giving
$E = ('"\\mu"'^2/2500 - 1/200)'"\\,\\hbar"'^2/(m a_0''^2) = 7/400 > 0$ in those units.
Pure algebra; no angle content.
'"\\end{proof}

\\begin{lemma}[Eccentricity exceeds one]
\\label{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one}
\\lean{IPhO2026.Problem1.B2.eccentricity_gt_one}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_angular_momentum_value, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime}
At "'$'"\\mu = 15/2"'$ the squared eccentricity strictly exceeds $1$: the conic is
a hyperbola, not an ellipse.
'"\\end{lemma}
\\begin{proof}
The added Hint-1 term "'$2 E L''^2/(m_{'"\\mathrm{red}} (k e"'^2)''^2)$ is a quotient
of positive quantities: $E > 0$
('"\\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}),
"'$m_{'"\\mathrm{red}} = m/2 > 0"'$, $L = 15'"\\hbar \\neq 0"'$, and $k, e > 0$; hence
$'"\\varepsilon"'^2 = 1 + ('"\\text{positive}) > 1"'$.
'"\\end{proof}

\\begin{theorem}[Eccentricity value (Hint 1, derivable)]
\\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_sq_eq}
\\lean{IPhO2026.Problem1.B2.eccentricity_sq_eq}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:ScalingRegime, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:unboundMu, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:IsAngularMomentumFactor}
Evaluation of the official Hint-1 formula for this scenario:
"'$'"\\varepsilon"'^2 = 67/4$ (so $'"\\varepsilon = \\sqrt{67}/2 > 1"'$).  This is the
page'"'s first hint recorded as a \\emph{derivable bridge lemma}, not an
assumed law; it is conclusion-free of angle data.
\\end{theorem}
\\begin{proof}
From the same laws as
\\cref{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:total_energy_pos}:
substitute "'$E = 7/400$ (in units $'"\\hbar"'^2/(m a_0''^2)$), $L = 15'"\\hbar"'$,
$m_{'"\\mathrm{red}} = m/2"'$, and the Bohr-radius identity into
$1 + 2 E L''^2/(m_{'"\\mathrm{red}}(k e"'^2)''^2)$; the units cancel and the
rational arithmetic gives $67/4$.
'"\\end{proof}

\\begin{theorem}[Polar conic form of the orbit (Hint 2, derivable)]
\\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:orbit_eq_conic}
\\lean{IPhO2026.Problem1.B2.orbit_eq_conic}
\\uses{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:semilatusRectum, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis, lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one, def:IPhO2026Problems_problem_IPhO_2026_1_B_2:CoulombScatteringData}
The page's second hint as a derivable bridge: the trajectory
"'$r = '"\\lVert \\mathrm{sep}\\,t \\rVert"'$ as a function of its own polar angle
$'"\\theta(t)"'$ is a conic -- there exist $'"\\varepsilon = \\sqrt{\\varepsilon"'^2} > 1$
and a symmetry-axis direction $'"\\theta_0"'$ (a priori unknown) such that for
all $t$, $'"\\varepsilon\\cos(\\theta(t) - \\theta_0) - 1 > 0"'$ and
$r = p/('"\\varepsilon\\cos(\\theta(t) - \\theta_0) - 1)"'$ (the periapsis branch
of the page'"'s form "'$r = a/(1 - '"\\varepsilon\\cos\\theta)"'$ up to the axis
orientation).
'"\\end{theorem}
\\begin{proof}
Set "'$u = 1/r$; angular-momentum conservation
$'"\\dot\\theta = L/(m_{\\mathrm{red}} r"'^2)$
turns Newton'"'s radial equation into Binet's linear equation
"'$u'"'' + u = m_{\\mathrm{red}} k e"'^2/L''^2$, whose solution with the periapsis
initial condition (radial speed zero at $t = 0$,
'"\\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:turningQuadratic_periapsis})
is "'$u = p''^{-1}('"\\varepsilon\\cos(\\theta - \\theta_0) - 1)"'$ with
$p = L''^2/(m_{'"\\mathrm{red}} k e"'^2)$ and $'"\\varepsilon"'$ matching
'"\\cref{def:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricitySq};
the unboundness "'$'"\\varepsilon > 1"'$
('"\\cref{lem:IPhO2026Problems_problem_IPhO_2026_1_B_2:eccentricity_gt_one})
selects the physical branch with positive denominator.
\\end{proof}

\\subsection*{Asymptotic relative velocity}

