\\begin{theorem}[Existence of the asymptotic relative velocity]
\\label{thm:IPhO2026Problems_problem_IPhO_2026_1_B_2:exists_asymptoticRelativeVelocity}
\\lean{IPhO2026.Problem1.B2.exists_asymptoticRelativeVelocity}
